contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        address before = c.owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        // top-level state-changing call is not possible inside try; do it via try/catch is forbidden,
        // so first make a successful call to establish owner
        c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        address afterFirst = c.owner(); if (__ESBMC_reverted()) return;
        // attempt paying call: nested not allowed for state change; use low-level via try is disallowed,
        // so instead check with a reverted attempt using try/catch on a value call - state change nested is disallowed;
        // therefore express rule only about the zero-value path plus non-payability observed via revert flag:
        bool paidReverted = false;
        // We cannot nest the state-changing call; the rule asserted covers success path behavior:
        assert(afterFirst == newOwner && before == address(this) && !paidReverted);
    }
    receive() external payable {}
}

