        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        address before;
        try c.owner() returns (address __r) { before = __r; } catch { return; }
        bool reverted;
        try c.setOwner(newOwner) {} catch { return; }
        address afterFirst;
        try c.owner() returns (address __r) { afterFirst = __r; } catch { return; }
        bool paidReverted = false;
        assertTrue(afterFirst == newOwner && before == address(this) && !paidReverted);
    }

